('<tr><td>4515, 4518</td><td>Domestic and external debt</td><td>Quarterly</td><td>Breakdown, quarterly change, chart</td></tr>', '<tr><td>4515، 4518</td><td>ދާޚިލީ ދަރަނި އަދި ބޭރުގެ ދަރަނި</td><td>ކުއާޓަރަކުން</td><td>ބައިބައިކުރުން، ކުއާޓަރުގެ ބަދަލު، ޗާޓު</td></tr>'),
('<tr><td>4516, 4517, 4519, 4520</td><td>Central government and guaranteed, domestic and external</td><td>Quarterly</td><td>Breakdown bar</td></tr>', '<tr><td>4516، 4517، 4519، 4520</td><td>މަރުކަޒީ ސަރުކާރާއި ގެރެންޓީ، ދާޚިލީ އަދި ބޭރު</td><td>ކުއާޓަރަކުން</td><td>ބައިބައިކުރުމުގެ ބާރ</td></tr>'),
('<tr><td>4522</td><td>Total outstanding debt as a share of GDP</td><td>Quarterly</td><td>Water level, % of GDP chart</td></tr>', '<tr><td>4522</td><td>ޖީޑީޕީގެ ނިސްބަތުން ޖުމްލަ ދަރަނި</td><td>ކުއާޓަރަކުން</td><td>ފެނުގެ މިންވަރު، ޖީޑީޕީގެ ނިސްބަތުގެ ޗާޓު</td></tr>'),
('<tr><td>4523, 4526</td><td>Domestic and external debt as a share of GDP</td><td>Quarterly</td><td>Breakdown</td></tr>', '<tr><td>4523، 4526</td><td>ޖީޑީޕީގެ ނިސްބަތުން ދާޚިލީ ދަރަނި އަދި ބޭރުގެ ދަރަނި</td><td>ކުއާޓަރަކުން</td><td>ބައިބައިކުރުން</td></tr>'),
('<tr><td>38</td><td>GDP at market price</td><td>Annual</td><td>Checking the ratio</td></tr>', '<tr><td>38</td><td>ބާޒާރު އަގުން ޖީޑީޕީ</td><td>އަހަރަކުން</td><td>ނިސްބަތް ޗެކްކުރުން</td></tr>'),
('<tr><td>1999</td><td>Total revenue and grants</td><td>Monthly</td><td>Revenue figures</td></tr>', '<tr><td>1999</td><td>ޖުމްލަ އާމްދަނީއާއި އެހީ</td><td>މަހަކުން</td><td>އާމްދަނީގެ އަދަދުތައް</td></tr>'),
('<tr><td>2034</td><td>Total recurrent and capital expenditure</td><td>Monthly</td><td>Spending figures</td></tr>', '<tr><td>2034</td><td>ޖުމްލަ ރިކަރަންޓް އަދި ކެޕިޓަލް ޚަރަދު</td><td>މަހަކުން</td><td>ޚަރަދުގެ އަދަދުތައް</td></tr>'),
('<tr><td>2036, 2050, 2057</td><td>Salaries and pensions; grants and subsidies; capital spending</td><td>Monthly</td><td>Spending breakdown</td></tr>', '<tr><td>2036، 2050، 2057</td><td>މުސާރަ އަދި ޕެންޝަން؛ އެހީ އަދި ސަބްސިޑީ؛ ކެޕިޓަލް ޚަރަދު</td><td>މަހަކުން</td><td>ޚަރަދު ބައިބައިކުރުން</td></tr>'),
('<tr><td>2049</td><td>Financing and interest costs</td><td>Monthly</td><td>Interest figures</td></tr>', '<tr><td>2049</td><td>ފައިނޭންސިންގ ޚަރަދާއި އިންޓަރެސްޓް</td><td>މަހަކުން</td><td>އިންޓަރެސްޓުގެ އަދަދުތައް</td></tr>'),
('<tr><td>5226</td><td>Interest payments on central government external debt</td><td>Quarterly</td><td>Fallback for interest</td></tr>', '<tr><td>5226</td><td>މަރުކަޒީ ސަރުކާރުގެ ބޭރުގެ ދަރަންޏަށް ދައްކާ އިންޓަރެސްޓް</td><td>ކުއާޓަރަކުން</td><td>2049 ނުލިބިއްޖެނަމަ، އިންޓަރެސްޓަށް</td></tr>'),
('<tr><td>4039</td><td>US dollar exchange rate (MMA reference)</td><td>Monthly</td><td>Dollar conversion</td></tr>', '<tr><td>4039</td><td>އެމެރިކަން ޑޮލަރުގެ އެކްސްޗޭންޖް ރޭޓު (MMA ރެފަރެންސް)</td><td>މަހަކުން</td><td>ޑޮލަރަށް ބަދަލުކުރުން</td></tr>'),
